import { normalizeAssets, normalizePolicy, normalizeWorkspaces, resourceError, resourceState, resourceValue } from "./dashboard-state.js";

const root = document.querySelector("#root");
const state = { token: null, user: null, workspaces: [], workspace: null, page: location.hash.slice(1) || "overview", authMode: "login", resources: {} };
const resourceRoutes = (id) => ({
  policy: `/v1/workspaces/${id}/policy`, providers: `/v1/workspaces/${id}/ai-providers`, assets: `/v1/workspaces/${id}/assets`,
  connections: `/v1/workspaces/${id}/publishing-connections`, analytics: `/v1/workspaces/${id}/analytics`,
  schedules: `/v1/workspaces/${id}/automation-schedules`, automationRuns: `/v1/workspaces/${id}/automation-runs`, usage: `/v1/workspaces/${id}/usage`,
});
const esc = (value) => String(value ?? "").replace(/[&<>"']/g, (char) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[char]));
const apiMessage = (error) => error?.error?.message || error?.message || "The Worker API could not complete this request.";

async function api(path, options = {}) {
  const headers = { "content-type": "application/json", ...(options.headers || {}) };
  if (state.token) headers.authorization = `Bearer ${state.token}`;
  const response = await fetch(path, { ...options, headers });
  let payload = null; try { payload = await response.json(); } catch { /* empty response */ }
  if (!response.ok) { const error = new Error(apiMessage(payload)); error.status = response.status; error.payload = payload; throw error; }
  return payload?.data;
}

function toast(message, bad = false) { const element = document.createElement("div"); element.className = `toast${bad ? " bad" : ""}`; element.textContent = message; document.body.append(element); setTimeout(() => element.remove(), 4500); }
function loading() { root.innerHTML = `<div class="auth"><div class="brand"><span class="mark"></span>VantaForge</div><div class="auth-card"><p class="muted">Loading authenticated workspace state…</p></div></div>`; }
function blocker(title, message) { return `<div class="blocked-box"><h3>${esc(title)}</h3><p class="muted">${esc(message)}</p></div>`; }
function resourceBlock(name, resource) { if (!resource || resource.status === "loading") return blocker(`${name} is loading`, "Waiting for the authenticated Worker response."); if (resource.status === "error") return blocker(`${name} unavailable`, resource.error); return ""; }
function data(name, fallback) { return resourceValue(state.resources[name], fallback); }

function authView() {
  root.innerHTML = `<div class="auth"><div class="brand"><span class="mark"></span>VantaForge</div><div class="auth-card"><div class="eyebrow">Creator operations, with evidence</div><h1>${state.authMode === "login" ? "Enter your workspace." : "Create your workspace."}</h1><p class="muted">Only authenticated Worker responses are rendered. No sample dashboard is included.</p><div class="auth-tabs"><button class="${state.authMode === "login" ? "active" : ""}" data-auth="login">Log in</button><button class="${state.authMode === "signup" ? "active" : ""}" data-auth="signup">Sign up</button></div><form id="auth-form" class="stack"><div class="field ${state.authMode === "signup" ? "" : "hidden"}"><label>Display name</label><input name="display_name" autocomplete="name"></div><div class="field"><label>Email</label><input name="email" type="email" autocomplete="email" required></div><div class="field"><label>Password</label><input name="password" type="password" autocomplete="current-password" required minlength="12"></div><button class="primary">${state.authMode === "login" ? "Log in" : "Create account"}</button><div id="auth-error" class="error"></div></form></div></div>`;
  document.querySelectorAll("[data-auth]").forEach((button) => { button.onclick = () => { state.authMode = button.dataset.auth; authView(); }; });
  document.querySelector("#auth-form").onsubmit = async (event) => { event.preventDefault(); try { const response = await api(`/v1/auth/${state.authMode === "login" ? "login" : "signup"}`, { method: "POST", body: JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); state.token = response.token; state.user = response.user; await loadWorkspaces(); render(); } catch (error) { document.querySelector("#auth-error").textContent = apiMessage(error.payload); } };
}

async function loadWorkspaces() {
  const response = await api("/v1/workspaces");
  state.workspaces = normalizeWorkspaces(response);
  if (state.workspace) state.workspace = state.workspaces.find((item) => item.id === state.workspace.id) || null;
  if (!state.workspace && state.workspaces[0]) state.workspace = state.workspaces[0];
  if (state.workspace) await loadWorkspace(state.workspace.id);
}

async function loadWorkspace(id) {
  state.workspace = state.workspaces.find((item) => item.id === id) || await api(`/v1/workspaces/${id}`);
  const routes = resourceRoutes(id);
  for (const [name, path] of Object.entries(routes)) {
    state.resources[name] = resourceState("loading");
    try { const response = await api(path); state.resources[name] = resourceState("ready", name === "assets" ? normalizeAssets(response) : name === "policy" ? normalizePolicy(response) : response); }
    catch (error) { state.resources[name] = resourceError(apiMessage(error.payload) || error); }
  }
}

function header(title, copy, action = "") { return `<div class="page-head"><div><div class="eyebrow">${esc(state.workspace?.name || "Workspace")} / ${esc(title)}</div><h1>${copy}</h1></div>${action}</div>`; }
function noWorkspace() { return `<div class="auth-card"><h2>No workspace selected</h2><p class="muted">The authenticated account has no workspace yet. Create one to load policy and resource state.</p><form id="new-workspace" class="stack"><div class="field"><label>Name</label><input name="name" required></div><div class="field"><label>Timezone</label><input name="timezone" required value="${esc(Intl.DateTimeFormat().resolvedOptions().timeZone)}"></div><button class="primary">Create workspace</button></form></div>`; }
function overview() { const policy = data("policy", {}), assets = data("assets", []), analytics = data("analytics", []), providers = data("providers", []), connections = data("connections", []); return header("Command center", "Operate from what is real.", `<div class="actions"><button class="secondary" data-page="settings">Workspace settings</button><button class="primary" data-page="assets">Asset readiness</button></div>`) + `<div class="grid"><div class="card span-3"><div class="label">Workspace</div><div class="metric">${esc(state.workspace.name)}</div><div class="subtle">${esc(state.workspace.timezone)}</div></div><div class="card span-3"><div class="label">Automation</div><div class="metric">${esc(policy?.mode || "—")}</div><div class="subtle">${policy?.stop_switch ? "Stop switch is on" : "Stop switch is off"}</div></div><div class="card span-3"><div class="label">Assets returned</div><div class="metric">${state.resources.assets?.status === "ready" ? assets.length : "—"}</div><div class="subtle">Worker response only</div></div><div class="card span-3"><div class="label">Analytics runs</div><div class="metric">${state.resources.analytics?.status === "ready" ? analytics.length : "—"}</div><div class="subtle">No fabricated metrics</div></div><div class="card span-7"><h2>Workspace readiness</h2>${resourceBlock("Provider status", state.resources.providers)}${resourceBlock("Asset status", state.resources.assets)}${resourceBlock("Publishing status", state.resources.connections)}${!resourceBlock("Provider status", state.resources.providers) ? `<div class="row"><span>Verified AI provider</span><span class="chip ${providers.some((item) => item.status === "verified") ? "" : "warn"}">${providers.find((item) => item.status === "verified")?.name || "Not verified"}</span></div>` : ""}${!resourceBlock("Publishing status", state.resources.connections) ? `<div class="row"><span>Active publishing connections</span><span class="chip neutral">${connections.filter((item) => item.credential_status === "active").length}</span></div>` : ""}</div><div class="card span-5"><h2>Evidence boundary</h2><p class="muted">Metrics, ideas, quality scores, statuses and post URLs appear only after their API response exists.</p><div class="actions"><button class="secondary" data-page="analytics">Analytics</button><button class="secondary" data-page="review">Quality review</button></div></div></div>`; }
function assets() { const resource = state.resources.assets, rows = data("assets", []); return header("Asset library", "Make readiness visible.", `<button class="primary" data-action="upload-help">Upload contract</button>`) + `<div class="grid"><div class="card span-8"><h2>Workspace assets</h2>${resourceBlock("Assets", resource)}${resource?.status === "ready" ? (rows.length ? `<table class="data-table"><thead><tr><th>File</th><th>Readiness</th><th>Licensing</th><th>Scan</th></tr></thead><tbody>${rows.map((asset) => `<tr><td>${esc(asset.original_filename)}<br><span class="subtle">${esc(asset.media_type)} · ${asset.bytes ?? "—"} bytes</span></td><td><span class="chip ${asset.status === "ready" ? "" : "blocked"}">${esc(asset.status)}</span><br><span class="subtle">${esc(asset.blocked_reason || "No blocker returned")}</span></td><td>${esc(asset.licensing?.type || "unconfigured")}<br><span class="subtle">Rights ${asset.licensing?.rights_confirmed ? "confirmed" : "not confirmed"}</span></td><td>${esc(asset.scan_status)}</td></tr>`).join("")}</tbody></table>` : `<div class="empty">No assets have been returned for this workspace.</div>`) : ""}</div><div class="card span-4">${blocker("Readiness is server-owned", "Upload completion requires checksum, duration, dimensions and licensing metadata. An unavailable scanner remains an explicit blocker; the client never upgrades an asset locally.")}</div></div>`; }
function settings() { const policy = data("policy", {}), providers = data("providers", []); return header("Settings", "Keep automation reversible.") + `<div class="grid"><div class="card span-7">${resourceBlock("Automation policy", state.resources.policy)}${state.resources.policy?.status === "ready" ? `<h2>Automation policy</h2><form id="policy-form" class="stack"><div class="form-grid"><div class="field"><label>Mode</label><select name="mode"><option value="assisted" ${policy.mode === "assisted" ? "selected" : ""}>Assisted</option><option value="autopilot" ${policy.mode === "autopilot" ? "selected" : ""}>Autopilot</option></select></div><div class="field"><label>Review cadence</label><select name="review_mode"><option value="every_short" ${policy.review_mode === "every_short" ? "selected" : ""}>Every short</option><option value="after_n_shorts" ${policy.review_mode === "after_n_shorts" ? "selected" : ""}>After N shorts</option><option value="none" ${policy.review_mode === "none" ? "selected" : ""}>No scheduled review</option></select></div><div class="field"><label>Daily spend limit (USD)</label><input name="daily_spend_limit" type="number" step="0.01" value="${esc(policy.daily_spend_limit ?? "")}"></div><div class="field"><label>Per-job cost limit (USD)</label><input name="per_job_cost_limit" type="number" step="0.01" value="${esc(policy.per_job_cost_limit ?? "")}"></div></div><div class="field"><label>Enabled capabilities</label><div class="check-list">${["idea_discovery", "production", "review", "publishing", "analytics"].map((capability) => `<label class="check"><input type="checkbox" name="capability" value="${capability}" ${Array.isArray(policy.enabled_capabilities) && policy.enabled_capabilities.includes(capability) ? "checked" : ""}> ${capability.replace("_", " ")}</label>`).join("")}</div></div><label class="check"><input type="checkbox" name="stop_switch" ${policy.stop_switch ? "checked" : ""}> Reversible stop switch — prevent new automated work</label><button class="primary">Save policy</button></form>` : ""}</div><div class="card span-5"><h2>Workspace</h2><form id="workspace-form" class="stack"><div class="field"><label>Name</label><input name="name" required value="${esc(state.workspace.name)}"></div><div class="field"><label>Timezone</label><input name="timezone" required value="${esc(state.workspace.timezone)}"></div><button class="secondary">Save workspace</button></form><hr style="border:0;border-top:1px solid var(--line);margin:22px 0"><h2>Session</h2><button class="danger" data-action="logout">Log out</button></div><div class="card span-12"><h2>AI provider settings</h2><p class="tabs-note">Keys are write-only and never rendered or persisted by this client.</p>${resourceBlock("Provider catalog", state.resources.providers)}${state.resources.providers?.status === "ready" ? providers.map((provider) => `<div class="row"><div><strong>${esc(provider.name)}</strong><div class="subtle">${esc(provider.status)}${provider.selected_model ? ` · ${esc(provider.selected_model)}` : ""}${provider.last_error_code ? ` · ${esc(provider.last_error_code)}` : ""}</div></div><div class="actions"><button class="secondary" data-action="credential" data-provider="${esc(provider.id)}">Set key</button><button class="secondary" data-action="verify" data-provider="${esc(provider.id)}" ${provider.credential_configured ? "" : "disabled"}>Verify</button><select data-action="model" data-provider="${esc(provider.id)}" ${provider.status === "verified" ? "" : "disabled"}><option>Select model</option>${(provider.models || []).map((model) => `<option value="${esc(model.id)}" ${model.id === provider.selected_model ? "selected" : ""}>${esc(model.label)}</option>`).join("")}</select></div></div>`).join("") : ""}</div></div>`; }
function connections() { const resource = state.resources.connections, rows = data("connections", []); return header("Connections", "Connect only with platform consent.") + `<div class="grid"><div class="card span-8"><h2>Publishing connections</h2>${resourceBlock("Publishing connections", resource)}${resource?.status === "ready" ? (rows.length ? rows.map((connection) => `<div class="row"><div><strong>${esc(connection.platform)}</strong><div class="subtle">Account ${esc(connection.account_id || "not returned")} · scopes ${Array.isArray(connection.scopes) ? connection.scopes.length : 0}</div></div><div class="actions"><span class="chip ${connection.credential_status === "active" ? "" : "warn"}">${esc(connection.credential_status)}</span><button class="secondary" disabled title="Unavailable: no supported OAuth/revoke contract is exposed to this dashboard">Revoke unavailable</button></div></div>`).join("") : `<div class="empty">No publishing connections have been returned for this workspace.</div>`) : ""}</div><div class="card span-4">${blocker("Publishing actions unavailable", "The dashboard reads existing connections only. OAuth connect and revoke are disabled until the deployed Worker contract is confirmed for this client; no nonexistent route is called.")}</div></div>`; }
function analytics() { const resource = state.resources.analytics, runs = data("analytics", []); return header("Analytics", "Use evidence, not guesses.") + `<div class="grid"><div class="card span-8"><h2>Persisted analytics runs</h2>${resourceBlock("Analytics", resource)}${resource?.status === "ready" ? (runs.length ? runs.map((run) => { const item = run.data || run; return `<div class="row"><div><strong>${esc(item.platform)} · ${esc(item.status)}</strong><div class="subtle">${esc(item.window?.start || "")} → ${esc(item.window?.end || "")} · ${Array.isArray(item.metrics) ? item.metrics.length : 0} metrics</div></div><span class="chip ${item.blocker ? "blocked" : item.status === "succeeded" ? "" : "warn"}">${esc(item.blocker?.code || item.status)}</span></div>`; }).join("") : `<div class="empty">No analytics runs have been returned for this workspace.</div>`) : ""}</div><div class="card span-4">${blocker("Fresh analytics unavailable", "This dashboard renders persisted analytics responses only. Fetching a new run is disabled until a confirmed deployed Worker route is available; no nonexistent route is called.")}</div></div>`; }
function usage() { const resource=state.resources.usage, value=data("usage",null); const accounts=value?.accounts||[], ledger=value?.ledger||[]; return header("Usage", "Billing evidence, allowance, and audit state.")+`<div class="grid"><div class="card span-4"><div class="label">Billing</div><div class="metric">${esc(value?.billing_status||"—")}</div><div class="subtle">${esc(value?.blocker?.code||"Verified evidence required")}</div></div><div class="card span-4"><div class="label">Plan</div><div class="metric">${esc(value?.entitlement?.display_name||"No entitlement")}</div><div class="subtle">Allowance ${esc(value?.entitlement?.allowance_microusd??"—")} μUSD</div></div><div class="card span-4"><div class="label">Uncertainty</div><div class="metric">${esc(value?.uncertainty||"—")}</div><div class="subtle">Server-reported only</div></div><div class="card span-12"><h2>Period accounts</h2>${resourceBlock("Usage",resource)}${resource?.status==="ready"?(accounts.length?accounts.map((a)=>`<div class="row"><span>${esc(a.user_id)}</span><span>${esc(a.settled_microusd)} settled · ${esc(a.reserved_microusd)} reserved / ${esc(a.budget_microusd)} μUSD</span></div>`).join(""):`<div class="empty">No active period account is available.</div>`):""}</div><div class="card span-12"><h2>Immutable audit ledger</h2>${resource?.status==="ready"?(ledger.length?ledger.map((item)=>`<div class="row"><span>${esc(item.kind)} · ${esc(item.amount_microusd)} μUSD</span><span class="subtle">${esc(item.uncertainty)} · ${esc(item.created_at)}</span></div>`).join(""):`<div class="empty">No usage events have been returned.</div>`):""}</div></div>`; }
function automation() { const schedules=data("schedules",[]), runs=data("automationRuns",[]); const scheduleState=state.resources.schedules, runState=state.resources.automationRuns; return header("Automation", "Durable runs, visible and controllable.")+`<div class="grid"><div class="card span-12"><h2>Schedules</h2>${resourceBlock("Schedules",scheduleState)}${scheduleState?.status==="ready"?(schedules.length?schedules.map((item)=>`<div class="row"><div><strong>${esc(item.name)}</strong><div class="subtle">${esc(item.status)} · every ${esc(item.cadence_minutes)} minutes${item.blocker_code?` · ${esc(item.blocker_code)}`:""}</div></div><div class="actions">${item.status==="active"?`<button class="secondary" data-action="schedule-control" data-id="${esc(item.id)}" data-control="pause">Pause</button>`:item.status!=="cancelled"?`<button class="secondary" data-action="schedule-control" data-id="${esc(item.id)}" data-control="resume">Resume</button>`:""}${item.status!=="cancelled"?`<button class="danger" data-action="schedule-control" data-id="${esc(item.id)}" data-control="cancel">Cancel</button>`:""}</div></div>`).join(""):`<div class="empty">No schedules have been returned.</div>`):""}</div><div class="card span-12"><h2>Runs</h2>${resourceBlock("Automation runs",runState)}${runState?.status==="ready"?(runs.length?runs.map((run)=>`<div class="row"><div><strong>${esc(run.current_step||"scheduled")} · ${esc(run.status)}</strong><div class="subtle">${esc(run.scheduled_for)}${run.blocker_code?` · ${esc(run.blocker_code)}`:""}</div></div><div class="actions">${run.status==="waiting_review"?`<button class="primary" data-action="approve-run" data-id="${esc(run.id)}">Approve</button>`:""}${["queued","running","retry_scheduled","waiting_review"].includes(run.status)?`<button class="danger" data-action="cancel-run" data-id="${esc(run.id)}">Cancel</button>`:""}</div></div>`).join(""):`<div class="empty">No upcoming, running, blocked, completed, or cancelled runs have been returned.</div>`):""}</div></div>`; }
function unavailable(title, endpoint) { return header(title, title === "Review" ? "Review only what the Worker can prove." : title === "Production" ? "Production needs a real job." : "Scout ideas with evidence.") + `<div class="grid"><div class="card span-8">${blocker(`${title} collection unavailable`, `The Worker exposes ${endpoint} detail by ID, but no workspace collection route. This view remains empty until a real resource response is available.`)}</div><div class="card span-4"><h2>Contract</h2><p class="code">GET /v1/${endpoint}/:id</p></div></div>`; }

function render() {
  if (!state.user) return authView();
  if (!state.workspace) { root.innerHTML = `<div class="auth"><div class="brand"><span class="mark"></span>VantaForge</div>${noWorkspace()}</div>`; bind(); return; }
  const pages = ["overview", "automation", "ideas", "production", "review", "assets", "usage", "analytics", "connections", "settings"];
  const content = state.page === "overview" ? overview() : state.page === "automation" ? automation() : state.page === "assets" ? assets() : state.page === "usage" ? usage() : state.page === "settings" ? settings() : state.page === "connections" ? connections() : state.page === "analytics" ? analytics() : state.page === "ideas" ? unavailable("Idea Scout", "idea-runs") : state.page === "production" ? unavailable("Production", "production-jobs") : unavailable("Review", "quality-gates");
  root.innerHTML = `<div class="shell"><header class="top"><div class="brand"><span class="mark"></span>VantaForge</div><div class="top-actions"><select class="workspace-switcher" id="workspace-select">${state.workspaces.map((workspace) => `<option value="${esc(workspace.id)}" ${workspace.id === state.workspace.id ? "selected" : ""}>${esc(workspace.name)}</option>`).join("")}<option value="__new">+ New workspace</option></select><span>${esc(state.user.display_name)}</span><span class="avatar">${esc(state.user.display_name.slice(0, 2).toUpperCase())}</span></div></header><div class="layout"><nav>${pages.slice(0, 5).map((page) => `<button class="${state.page === page ? "active" : ""}" data-page="${page}">${page === "ideas" ? "Idea Scout" : page[0].toUpperCase() + page.slice(1)}</button>`).join("")}<h5>Manage</h5>${pages.slice(5).map((page) => `<button class="${state.page === page ? "active" : ""}" data-page="${page}">${page[0].toUpperCase() + page.slice(1)}</button>`).join("")}</nav><main>${content}</main></div></div>`; bind();
}

async function action(element) {
  try {
    const id = state.workspace.id;
    if (element.dataset.action === "logout") { await api("/v1/auth/logout", { method: "POST" }); state.token = null; state.user = null; state.workspace = null; render(); return; }
    if (element.dataset.action === "credential") { const apiKey = prompt(`Enter the ${element.dataset.provider} API key. It is sent once and never displayed.`); if (!apiKey) return; await api(`/v1/workspaces/${id}/ai-providers/${element.dataset.provider}/credentials`, { method: "PUT", body: JSON.stringify({ api_key: apiKey }) }); toast("Credential saved as write-only configuration"); await loadWorkspace(id); render(); return; }
    if (element.dataset.action === "verify") { await api(`/v1/workspaces/${id}/ai-providers/${element.dataset.provider}/verify`, { method: "POST", body: "{}" }); toast("Provider verified by the Worker"); await loadWorkspace(id); render(); return; }
    if (element.dataset.action === "model") { if (!element.value || element.value === "Select model") return; await api(`/v1/workspaces/${id}/ai-providers/${element.dataset.provider}/models`, { method: "PATCH", body: JSON.stringify({ model: element.value }) }); toast("Model selection saved"); await loadWorkspace(id); render(); return; }
    if (element.dataset.action === "upload-help") toast("Upload completion requires the server checksum, media metadata and licensing contract; no local readiness is claimed.");
    if (element.dataset.action === "schedule-control") { await api(`/v1/automation-schedules/${element.dataset.id}/control`,{method:"POST",body:JSON.stringify({action:element.dataset.control})}); await loadWorkspace(id); render(); return; }
    if (element.dataset.action === "cancel-run") { await api(`/v1/automation-runs/${element.dataset.id}/cancel`,{method:"POST",body:"{}"}); await loadWorkspace(id); render(); return; }
    if (element.dataset.action === "approve-run") { const reason=prompt("Approval reason (optional)"); await api(`/v1/automation-runs/${element.dataset.id}/approve`,{method:"POST",body:JSON.stringify(reason?{reason}:{})}); await loadWorkspace(id); render(); return; }
  } catch (error) { toast(apiMessage(error.payload) || error.message, true); }
}

function bind() {
  document.querySelectorAll("[data-page]").forEach((element) => { element.onclick = () => { state.page = element.dataset.page; history.pushState({}, "", `#${state.page}`); render(); }; });
  document.querySelectorAll("[data-action]").forEach((element) => { element.onclick = () => action(element); });
  const select = document.querySelector("#workspace-select"); if (select) select.onchange = async () => { if (select.value === "__new") { const name = prompt("Workspace name"); if (!name) return; try { const workspace = await api("/v1/workspaces", { method: "POST", body: JSON.stringify({ name, timezone: Intl.DateTimeFormat().resolvedOptions().timeZone }) }); state.workspaces.unshift(workspace); state.workspace = workspace; await loadWorkspace(workspace.id); render(); } catch (error) { toast(apiMessage(error.payload), true); } } else { await loadWorkspace(select.value); render(); } };
  document.querySelectorAll('[data-action="model"]').forEach((element) => { element.onchange = () => action(element); });
  const newForm = document.querySelector("#new-workspace"); if (newForm) newForm.onsubmit = async (event) => { event.preventDefault(); try { const workspace = await api("/v1/workspaces", { method: "POST", body: JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); state.workspaces = [workspace]; state.workspace = workspace; await loadWorkspace(workspace.id); render(); } catch (error) { toast(apiMessage(error.payload), true); } };
  const policyForm = document.querySelector("#policy-form"); if (policyForm) policyForm.onsubmit = async (event) => { event.preventDefault(); const form = new FormData(event.currentTarget); try { await api(`/v1/workspaces/${state.workspace.id}/policy`, { method: "PUT", body: JSON.stringify({ mode: form.get("mode"), review_mode: form.get("review_mode"), daily_spend_limit: form.get("daily_spend_limit") ? Number(form.get("daily_spend_limit")) : null, per_job_cost_limit: form.get("per_job_cost_limit") ? Number(form.get("per_job_cost_limit")) : null, enabled_capabilities: form.getAll("capability"), stop_switch: form.get("stop_switch") === "on" }) }); toast("Automation policy saved"); await loadWorkspace(state.workspace.id); render(); } catch (error) { toast(apiMessage(error.payload), true); } };
  const workspaceForm = document.querySelector("#workspace-form"); if (workspaceForm) workspaceForm.onsubmit = async (event) => { event.preventDefault(); try { const workspace = await api(`/v1/workspaces/${state.workspace.id}`, { method: "PUT", body: JSON.stringify(Object.fromEntries(new FormData(event.currentTarget))) }); state.workspace = workspace; state.workspaces = state.workspaces.map((item) => item.id === workspace.id ? workspace : item); render(); toast("Workspace settings saved"); } catch (error) { toast(apiMessage(error.payload), true); } };
}

async function boot() { loading(); try { const response = await api("/v1/auth/me"); state.user = response.user; await loadWorkspaces(); render(); } catch (error) { if (error.status === 401) authView(); else root.innerHTML = `<div class="auth"><div class="brand"><span class="mark"></span>VantaForge</div>${blocker("Worker unavailable", apiMessage(error.payload))}</div>`; } }
window.addEventListener("popstate", () => { state.page = location.hash.slice(1) || "overview"; render(); });
boot();
